requests.testScript:
if (pw.response.status === 200) {
  const body = pw.response.body;
  pw.env.set('token', body.accessToken);
  console.log('✅ Token obtenido: ' + body.accessToken.substring(0, 20) + '...');
}

if (pw.response.status === 201) {
  const body = pw.response.body;
  pw.env.set('salaId', body.salaId);
  pw.env.set('salaCodigo', body.codigo);
  console.log('✅ Sala creada: ' + body.codigo);
  console.log('🔗 Enlace: ' + body.enlace);
}

if (pw.response.status === 200) {
  const body = pw.response.body;
  console.log('✅ Sala encontrada: ' + body.nombre);
  console.log('📊 Estado: ' + body.estado);
  console.log('👥 Participantes: ' + body.totalParticipantes);
}

if (pw.response.status === 200) {
  const body = pw.response.body;
  console.log('✅ Salas donde soy HOST: ' + body.salas.length);
  body.salas.forEach(s => console.log('  - ' + s.nombre + ' (' + s.codigo + ')'));
}

if (pw.response.status === 200) {
  const body = pw.response.body;
  console.log('✅ Salas programadas: ' + body.salas.length);
  body.salas.forEach(s => console.log('  - ' + s.nombre + ' | ' + s.fechaInicio));
}

if (pw.response.status === 200) {
  const body = pw.response.body;
  console.log('✅ Detalle de sala: ' + body.nombre);
  console.log('🔗 Enlace: ' + body.enlace);
  console.log('👥 Participantes: ' + body.totalParticipantes);
  console.log('👤 Creador: ' + body.creador.nombre + ' ' + body.creador.apellido);
  body.participantes.forEach(p => console.log('  - ' + p.nombre + ' (' + p.rol + ')'));
}

